import argparse,json,os,html
from pathlib import Path
import atlas_eur_rc103 as stats
from datetime import datetime,timezone
VERSION='eur-rc10.4-dashboard'
def build(diag,report):
    s=diag['registration']['snapshot']; m=s['macro_score']; now=stats.stamp(report['generated_at_utc']); d=now.astimezone(stats.base.prev.BRT).date(); periods={'day':d.isoformat(),'week':f'{d.isocalendar().year}-W{d.isocalendar().week:02d}','month':d.strftime('%Y-%m')}
    esc=lambda x:html.escape(str(x)); fmt=lambda x,n=2: '—' if x is None else f'{x:.{n}f}'.replace('.',',')
    cards=''
    for h,name in [('day','Diário'),('week','Semanal'),('month','Mensal')]:
        r=next((r for r in report['history'] if r['horizon']==h and r['period']==periods[h] and r['status']!='invalid'),None); a=report['horizons'][h]
        cards+=f'<section><small>{name} · {periods[h]}</small><h2>{esc(r["bias"]) if r else "Aguardando registro"}</h2><p>Score: {fmt(r["score"] if r else None)}</p><small>Assertividade direcional</small><h2>{fmt(a["hit_rate_percent"])}%</h2><p>{a["hits"]} acertos · {a["misses"]} erros · {a["directional_count"]} amostras</p><p>Neutros: {a["neutral_hits"]}/{a["neutral_count"]}</p></section>'
    drivers=''.join(f'<tr><td>{name}</td><td>{fmt(m["components"][k].get("contribution"))}</td><td>{esc(m["components"][k].get("period","—"))}</td></tr>' for k,name in [('rates','Juros'),('inflation','Inflação'),('activity','Atividade'),('unemployment','Emprego'),('risk','Risco global')])
    rows=''.join(f'<tr><td>{esc(r["horizon"])}</td><td>{esc(r["period"])}</td><td>{fmt(r.get("score"))}</td><td>{fmt(r.get("return_percent"))}</td><td>{esc(r.get("outcome",r["status"]))}</td></tr>' for r in report['history']) or '<tr><td colspan="5">Sem histórico registrado</td></tr>'
    pts=sorted([r for r in report['history'] if r['horizon']=='day' and r['status']=='evaluated'],key=lambda r:r['period']); chart='Aguardando pelo menos dois registros diários avaliados.'
    if len(pts)>=2:
        prices=[r['entry']['price'] for r in pts]; lo,hi=min(prices),max(prices); span=hi-lo or 1; x=lambda i:30+i*540/(len(pts)-1); line=lambda ys:' '.join(f'{x(i):.2f},{y:.2f}' for i,y in enumerate(ys)); chart=f'<svg viewBox="0 0 600 220" role="img" aria-label="Score e preço inicial, escalas independentes"><polyline fill="none" stroke="#60a5fa" stroke-width="2" points="{line([110-r["score"]*.9 for r in pts])}"/><polyline fill="none" stroke="#fbbf24" stroke-width="2" points="{line([200-(p-lo)/span*180 for p in prices])}"/></svg><p>Azul: score (−100 a +100). Amarelo: preço inicial ({fmt(lo,5)} a {fmt(hi,5)}). Escalas independentes; somente registros diários avaliados.</p>'
    price=diag.get('latest_price') or {}; stamp=price.get('bar_end_utc','—')
    return f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas EUR Macro</title><style>*{{box-sizing:border-box}}body{{background:#0b111c;color:#e2e8f0;font:16px system-ui;margin:auto;max-width:1200px;padding:24px}}h1{{letter-spacing:2px}}small,p{{color:#a6b5c9}}section{{background:#131e2d;border:1px solid #253245;border-radius:12px;padding:20px;margin:12px 0}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}}h2{{margin:10px 0}}table{{width:100%;border-collapse:collapse}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #253245}}.scroll{{overflow:auto}}svg{{width:100%;max-height:260px}}strong{{color:#60a5fa}}</style><h1>ATLAS EUR MACRO</h1><p>RC10.4 · Pesquisa experimental · Relatório estático gerado em {esc(report['generated_at_utc'])}</p><section><small>Última leitura macroeconômica — não é previsão fixa</small><h2>{fmt(m['score'])} · {esc(m['bias'])}</h2><p>Cobertura: {fmt(m['coverage_percent'],0)}% · {esc(s['score_calculated_at_utc'])}</p><h2>EUR/USD {fmt(price.get('price'),5)}</h2><p>Yahoo Finance M5 · fechamento da vela: {esc(stamp)} · UTC</p></section><div class="grid">{cards}</div><section><h2>Drivers macroeconômicos</h2><table><tr><th>Componente</th><th>Contribuição</th><th>Período</th></tr>{drivers}</table></section><section><h2>Score × preço</h2>{chart}</section><section class="scroll"><h2>Histórico · {report['registered']} registros / {report['evaluated']} avaliados</h2><table><tr><th>Horizonte</th><th>Período</th><th>Score</th><th>Retorno %</th><th>Resultado</th></tr>{rows}</table></section><p>Janela experimental 04h–04h15 BRT; fechamento de referência 16h BRT. Sem custos, sem probabilidade calibrada. Dados não atualizam ao abrir este arquivo.</p></html>'''
def main():
    p=argparse.ArgumentParser();p.add_argument('--diagnostic',type=Path,required=True);p.add_argument('--statistics',type=Path,required=True);p.add_argument('--output',type=Path,default=Path('atlas_eur_dashboard.html'));a=p.parse_args();a.output.write_text(build(json.loads(a.diagnostic.read_text()),json.loads(a.statistics.read_text())),encoding='utf-8')
if __name__=='__main__':main()
